async function getUserUsage(userId) {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { tier: true }
  });
  const tier = user?.tier || "FREE";
  const stats = await getUserUsageStats(userId, tier);
  return {
    queriesThisMonth: stats.used,
    limit: stats.limit
  };
}
